def _tenant_sqlite_paths() -> list[Path]:
    paths: list[Path] = []
    if _is_server_mode():
        tenants_root = ROOT / "data" / "tenants"
        if tenants_root.is_dir():
            for entry in tenants_root.iterdir():
                if entry.is_dir():
                    db = entry / "app.db"
                    if db.is_file():
                        paths.append(db)
        for extra in (ROOT / "data" / "global" / "app.db", ROOT / "data" / "app.db"):
            if extra.is_file():
                paths.append(extra)
    else:
        paths.append(_db_path())
    return paths


